import { Blockbase } from '../Block/Blockbase';
import { TetrisGame } from '../TetrisGame';
export class PixelMap {
    tetrisGame: TetrisGame;
    width: number;
    height: number;
    pixels: Pixel[][] = [];
    numLineMax: number = -1;
    constructor(tetrisGame: TetrisGame, width: number, height: number) {
        this.tetrisGame = tetrisGame;
        this.numLineMax = height;
        this.width = width;
        this.height = height;
        this.Init();
    }
    Init() {
        for (let y = 0; y < this.height; ++y) {
            let pixelList: Pixel[] = [];
            for (let x = 0; x < this.width; ++x) {
                pixelList.push(new Pixel(this, 'rgba(0,0,0,0)', 'rgba(0,0,0,0.15)'));
            }
            this.pixels.push(pixelList);
        }
    }
    Update(block: Blockbase) {
        if (this.CheckCollision(block)) {
            // this.thisUpdateMat(block);

            this.tetrisGame.InitBlock();
            return false;
        }

        return true;
    }
    isDone() {
        if (this.numLineMax === 0) { return true; }
        // let numFill = 0;
        // for (let y = 0; y < 3; ++y) {
        //     let isFill = false;
        //     for (let x = 0; x < this.width; ++x) {
        //         if (this.pixels[y][x].isFill) {
        //             isFill = true;
        //         }
        //     }
        //     if (isFill) {
        //         numFill++;
        //     }
        // }
        // if (numFill > 2) {
        //     // console.log('done', numFill);
        //     return true;
        // }
        return false;
    }
    AddEmptyLine() {
        let temp: Pixel[][] = [];
        let pixelList: Pixel[] = [];
        for (let x = 0; x < this.width; ++x) {
            pixelList.push(new Pixel(this, 'rgba(0,0,0,0)', 'rgba(0,0,0,0.15)'));
        }
        temp.push(pixelList);
        temp.concat(this.pixels);
        console.log(temp);
        this.pixels = temp;
    }

    // thisUpdateMat(block: Blockbase) {
    //     const xIndex = block.vec.x + x;
    //     const yIndex = block.vec.y + y + 1;


    // }
    RemoveLine() {
        const lines = this.CheckLines();
        if (lines.length === 0) { return false; }
        let indexLine = 0;
        const tempPixel: Pixel[][] = [];

        for (let i = 0; i < lines.length; ++i) {
            let pixelList: Pixel[] = [];
            for (let x = 0; x < this.width; ++x) {
                pixelList.push(new Pixel(this, 'rgba(0,0,0,0)', 'rgba(0,0,0,0.15)'));
            }
            tempPixel.push(pixelList);
            this.tetrisGame.UpdateUINumofLine();
        }

        for (let i = 0; i < this.pixels.length; ++i) {
            if (lines[indexLine] === i) {
                indexLine++;
            } else {
                tempPixel.push(this.pixels[i]);
            }
        }
        this.pixels = tempPixel;
        return true;
    }
    IsOver() {
        // this.pixels[0][this.pixels[0]]
    }
    CheckLines() {
        const lines = [];
        for (let y = 0; y < this.pixels.length; ++y) {

            let needRemove = true;
            for (let x = 0; x < this.pixels[y].length; ++x) {
                if (!this.pixels[y][x].isFill) { needRemove = false; }
            }
            if (needRemove) {
                lines.push(y);
            }
        }
        return lines;
    }
    CheckCollision(block: Blockbase) {
        if (this.pixels.length === 0) { return undefined; }
        const mat = block.GetMat();

        let collided: boolean = false;
        for (let y = 0; y < mat.length; ++y) {
            for (let x = 0; x < mat[y].length; ++x) {
                const isFill = mat[y][x];
                if (isFill === 1) {
                    // check blow
                    let xIndex = block.vec.x + x;
                    let yIndex = block.vec.y + y + 1;
                    // console.log(yIndex, xIndex);
                    // console.log(this.pixels);
                    if (yIndex > this.height - 1 || this.pixels[yIndex][xIndex] && this.pixels[yIndex][xIndex].isFill) {
                        collided = true;
                    }
                }
            }
        }

        if (collided) {
            for (let y = 0; y < mat.length; ++y) {
                for (let x = 0; x < mat[y].length; ++x) {
                    const isFill = mat[y][x];
                    if (isFill === 1) {
                        const xIndex = block.vec.x + x;
                        const yIndex = block.vec.y + y + 1;

                        // console.log(yIndex, xIndex);
                        // console.log(this.pixels);

                        if (yIndex < this.height + 1) {
                            this.pixels[yIndex - 1][xIndex].isFill = true;
                            this.pixels[yIndex - 1][xIndex].colorFill = block.colorFill;
                        }
                    }
                }
            }
            return true;
        }
        return false;
    }
    ClonePixels() {
        const temp = [];
        for (let y = 0; y < this.pixels.length; ++y) {
            const tempSub = [];
            for (let x = 0; x < this.pixels[y].length; ++x) {
                tempSub.push(this.pixels[y][x].DeepCopy());
            }
            temp.push(tempSub);
        }
        return temp;
    }
    Render(ctx: CanvasRenderingContext2D) {
        // console.log(this.pixels);

        let needComputeMaxLine = true;


        for (let y = 0; y < this.pixels.length; ++y) {
            for (let x = 0; x < this.pixels[y].length; ++x) {


                if (this.pixels[y][x].isFill && needComputeMaxLine) {
                    this.numLineMax = y;
                    needComputeMaxLine = false;
                }


                this.pixels[y][x].Render(ctx, x, y);
            }
        }
        // console.log(this.numLineMax);
    }
}
export class Pixel {
    pixelMap: PixelMap;
    isFill: boolean = false;
    colorFill: string;
    colorStroke: string;
    width: number = 1;
    height: number = 1;
    constructor(pixelMap: PixelMap, colorFill: string, colorStroke: string) {
        this.pixelMap = pixelMap;
        this.colorFill = colorFill;
        this.colorStroke = colorStroke;
    }
    DeepCopy() {
        const p = new Pixel(this.pixelMap, this.colorFill, this.colorStroke);
        p.isFill = this.isFill;
        return p;
    }
    Render(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        // console.log(this.vec.x * this.scale, this.vec.y * this.scale);
        ctx.rect(x * this.pixelMap.tetrisGame.scaleForRender, y * this.pixelMap.tetrisGame.scaleForRender, this.width * this.pixelMap.tetrisGame.scaleForRender, this.height * this.pixelMap.tetrisGame.scaleForRender);
        ctx.closePath();
        ctx.fillStyle = this.colorFill;
        ctx.fill();
        ctx.strokeStyle = this.colorStroke;
        ctx.stroke();
    }
}